/**
 * Call ringtone (ADR 0012 Wave 6) — incoming ring + outgoing ringback.
 *
 * Plays the SAME looping ring files the mobile client ships, generated by
 * `scripts/gen-sounds.mjs` in the active sound family (docs/product/sound-credits.md):
 *   - incoming: C5+G5 double pair, one 2.60 s cadence period per file
 *   - outgoing: A4 ringback, one 3.40 s cadence period per file
 * Each file IS one full period (taps at the top, silence padding the rest), so
 * `loop = true` reproduces the cadence. Until 2026-10-20 desktop synthesized a
 * separate sine beep (C5+E5) with Web Audio, so the two platforms rang
 * differently; now both ring with identical audio.
 *
 * It honors the shared sound settings (master switch + volume), so muting the
 * app silences the ring too. Imperative, never in React state (CLAUDE.md §27);
 * fire-and-forget, never throws.
 */

import { useSoundSettings } from "./sound-settings";
import ringIncomingUrl from "./assets/ring-incoming.ogg";
import ringOutgoingUrl from "./assets/ring-outgoing.ogg";

type RingKind = "incoming" | "outgoing";

const RING_URLS: Record<RingKind, string> = {
  incoming: ringIncomingUrl,
  outgoing: ringOutgoingUrl,
};

const elements = new Map<RingKind, HTMLAudioElement>();
let activeKind: RingKind | null = null;

/** Effective ring level from the persisted sound settings (0 when muted). */
function ringVolume(): number {
  const { enabled, volume } = useSoundSettings.getState();
  return enabled ? volume : 0;
}

function getElement(kind: RingKind): HTMLAudioElement {
  let el = elements.get(kind);
  if (!el) {
    el = new Audio(RING_URLS[kind]);
    el.preload = "auto";
    el.loop = true;
    elements.set(kind, el);
  }
  return el;
}

/** Start (or switch) the looping ring. Idempotent for the same kind. */
export function startRingtone(kind: RingKind): void {
  if (activeKind === kind) return;
  stopRingtone();
  const volume = ringVolume();
  if (volume <= 0) return; // muted → stay silent (no active ring to leak)
  if (typeof Audio === "undefined") return;
  activeKind = kind;
  const el = getElement(kind);
  el.volume = volume;
  el.currentTime = 0;
  el.play().catch((err: unknown) => {
    // Autoplay policy or device issues — log, never crash a call.
    console.warn(`[ringtone] "${kind}" playback failed`, err);
  });
}

/** Stop the ring (safe to call when nothing is playing). */
export function stopRingtone(): void {
  const kind = activeKind;
  activeKind = null;
  if (!kind) return;
  const el = elements.get(kind);
  if (!el) return;
  el.pause();
  el.currentTime = 0;
}
